<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\DeliveryService;
use EventMenu\Services\OrderWorkflowService;
use EventMenu\Services\PaymentService;

Auth::requirePermission('orders.view');
if(Auth::role()==='kitchen')em_go('kitchen');
if(Auth::role()==='delivery')em_go('my-deliveries');
if(Auth::role()==='counter')em_go('counter-orders');
$tenantId=em_require_tenant();$unitId=Auth::unitId();
$settingsStmt=$pdo->prepare('SELECT settings FROM tenants WHERE id=?');$settingsStmt->execute([$tenantId]);$settings=json_decode((string)($settingsStmt->fetchColumn()?:'{}'),true);if(!is_array($settings))$settings=[];try{$tz=new DateTimeZone((string)($settings['timezone']??'America/Sao_Paulo'));}catch(Throwable){$tz=new DateTimeZone('America/Sao_Paulo');}$utc=new DateTimeZone('UTC');
function legacy_order_channel(string$c):string{return match($c){'counter'=>'Balcão','table'=>'Mesa','delivery'=>'Delivery','pickup'=>'Retirada','event'=>'Evento',default=>ucfirst($c)};}
function legacy_order_status(string$s):string{return match($s){'pending'=>'Novo','confirmed'=>'Confirmado','preparing'=>'Em Preparo','ready'=>'Pronto','out_for_delivery'=>'Saiu para Entrega','completed'=>'Concluído','cancelled'=>'Cancelado',default=>em_status_label($s)};}
function legacy_order_status_class(string$s):string{return match($s){'pending','confirmed'=>'new','preparing'=>'prep','ready'=>'ready','out_for_delivery'=>'delivery','completed'=>'done','cancelled'=>'cancelled',default=>''};}
$assertUnit=function(int$id)use($pdo,$tenantId,$unitId):void{if(!$unitId)return;$s=$pdo->prepare('SELECT id FROM orders WHERE id=? AND tenant_id=? AND unit_id=?');$s->execute([$id,$tenantId,$unitId]);if(!$s->fetchColumn())throw new RuntimeException('Este pedido pertence a outra unidade.');};
if($_SERVER['REQUEST_METHOD']==='POST'){
 em_post_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 try{$assertUnit($id);
  if($action==='status'){Auth::requirePermission('orders.manage');$status=(string)($_POST['status']??'');(new OrderWorkflowService())->transition($tenantId,$id,$status);em_flash('ok','Pedido atualizado.');}
  elseif($action==='assign-delivery'){Auth::requirePermission('delivery.assign');$user=(int)($_POST['delivery_user_id']??0);(new DeliveryService())->assign($tenantId,$id,$user>0?$user:null);em_flash('ok',$user?'Entregador atribuído.':'Entrega ficou sem entregador.');}
  elseif($action==='manual-pay'){
   Auth::requirePermission('payments.manage');$method=(string)($_POST['manual_method']??'');if(!in_array($method,['cash','card','pix','other'],true))throw new RuntimeException('Forma de pagamento inválida.');
   $sql='SELECT total_cents,status,payment_status FROM orders WHERE id=? AND tenant_id=?'.($unitId?' AND unit_id=?':'');$args=[$id,$tenantId];if($unitId)$args[]=$unitId;$s=$pdo->prepare($sql);$s->execute($args);$order=$s->fetch();if(!$order)throw new RuntimeException('Pedido não encontrado.');if(in_array($order['status'],['completed','cancelled'],true))throw new RuntimeException('Pedido finalizado/cancelado não pode receber pagamento.');if(!in_array($order['payment_status'],['unpaid','failed'],true))throw new RuntimeException('Este pedido não está disponível para recebimento manual.');
   $open=$pdo->prepare('SELECT COUNT(*) FROM payments WHERE tenant_id=? AND order_id=? AND provider<>"manual" AND status IN ("created","pending","authorized")');$open->execute([$tenantId,$id]);if((int)$open->fetchColumn()>0)throw new RuntimeException('Existe uma cobrança online em andamento.');
   $service=new PaymentService();$service->create($id,'manual','manual:'.$tenantId.':'.$id.':'.bin2hex(random_bytes(8)));$service->confirmVerified(['tenant_id'=>$tenantId,'order_id'=>$id,'provider'=>'manual','provider_payment_id'=>'MANUAL-'.strtoupper(bin2hex(random_bytes(8))),'amount_cents'=>(int)$order['total_cents'],'currency'=>'BRL','account_reference'=>'manual','manual_method'=>$method]);Auth::audit('payment.manual','order',(string)$id,['method'=>$method,'unit_id'=>$unitId]);em_flash('ok','Pagamento confirmado.');
  }
 }catch(Throwable$e){em_flash('error',$e->getMessage());}
 em_go('orders',['tab'=>(string)($_POST['tab']??'all'),'view'=>$id]);
}
$tabs=['all'=>['Todos',null],'new'=>['Novos',['pending','confirmed']],'preparing'=>['Em Preparo',['preparing','ready']],'out_for_delivery'=>['Saiu para Entrega',['out_for_delivery']],'completed'=>['Concluídos',['completed']]];$tab=(string)($_GET['tab']??'all');if(!isset($tabs[$tab]))$tab='all';
$sql='SELECT o.*,c.name customer_name,c.phone customer_phone,u.name delivery_name,rt.name table_name FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.assigned_delivery_user_id LEFT JOIN restaurant_tables rt ON rt.id=o.table_id WHERE o.tenant_id=?';$args=[$tenantId];if($unitId){$sql.=' AND o.unit_id=?';$args[]=$unitId;}$statuses=$tabs[$tab][1];if(is_array($statuses)&&$statuses){$marks=implode(',',array_fill(0,count($statuses),'?'));$sql.=' AND o.status IN ('.$marks.')';$args=[...$args,...$statuses];}$sql.=' ORDER BY COALESCE(o.scheduled_for,o.created_at) DESC,o.id DESC LIMIT 150';$s=$pdo->prepare($sql);$s->execute($args);$orders=$s->fetchAll();
if($unitId){$d=$pdo->prepare('SELECT DISTINCT u.id,u.name FROM users u WHERE u.tenant_id=? AND u.role="delivery" AND u.status="active" AND (NOT EXISTS (SELECT 1 FROM user_units ux WHERE ux.user_id=u.id) OR EXISTS (SELECT 1 FROM user_units uu WHERE uu.user_id=u.id AND uu.unit_id=?)) ORDER BY u.name');$d->execute([$tenantId,$unitId]);}else{$d=$pdo->prepare('SELECT id,name FROM users WHERE tenant_id=? AND role="delivery" AND status="active" ORDER BY name');$d->execute([$tenantId]);}$deliveries=$d->fetchAll();
$view=(int)($_GET['view']??0);$items=[];$viewOrder=null;if($view){$sql='SELECT o.*,c.name customer_name,c.phone customer_phone,u.name delivery_name,rt.name table_name FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.assigned_delivery_user_id LEFT JOIN restaurant_tables rt ON rt.id=o.table_id WHERE o.id=? AND o.tenant_id=?'.($unitId?' AND o.unit_id=?':'');$a=[$view,$tenantId];if($unitId)$a[]=$unitId;$v=$pdo->prepare($sql);$v->execute($a);$viewOrder=$v->fetch()?:null;if($viewOrder){$it=$pdo->prepare('SELECT oi.*,GROUP_CONCAT(oio.name_snapshot, ", ") option_names FROM order_items oi LEFT JOIN order_item_options oio ON oio.order_item_id=oi.id WHERE oi.order_id=? GROUP BY oi.id ORDER BY oi.id');$it->execute([$view]);$items=$it->fetchAll();}}
em_header('Pedidos','orders');
?>
<style>.legacy-orders-head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:15px}.legacy-orders-head h2{margin:0;font-size:23px}.legacy-orders-head p{margin:5px 0 0;color:var(--muted)}.legacy-order-tabs{display:flex;gap:5px;overflow:auto;border-bottom:1px solid var(--line);margin-bottom:16px}.legacy-order-tabs a{white-space:nowrap;padding:11px 14px;color:#777789;font-size:12px;font-weight:800;border-bottom:2px solid transparent}.legacy-order-tabs a.active{color:var(--accent);border-color:var(--accent)}.legacy-order-list{display:grid;gap:10px}.legacy-order-row{display:grid;grid-template-columns:125px minmax(170px,1.2fr) 135px 140px 120px 120px;gap:14px;align-items:center;background:#fff;border:1px solid var(--line);border-radius:14px;padding:15px 16px}.legacy-order-id strong{font-size:15px}.legacy-order-id small,.legacy-order-customer small{display:block;color:var(--muted);font-size:10px;margin-top:4px}.legacy-order-customer strong{display:block}.legacy-order-price{font-size:15px;font-weight:900}.legacy-status{display:inline-flex;padding:6px 9px;border-radius:999px;font-size:10px;font-weight:900;background:#f1eff8;color:#5f4aaf}.legacy-status.new{background:#eee9ff;color:#6247e7}.legacy-status.prep{background:#fff0dc;color:#b76c00}.legacy-status.ready{background:#e6f8ee;color:#138056}.legacy-status.delivery{background:#e6f2ff;color:#1872bd}.legacy-status.done{background:#e8f7ef;color:#138056}.legacy-status.cancelled{background:#fff0f2;color:#c64152}.legacy-order-detail{margin-bottom:16px}.legacy-order-detail-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:16px}.legacy-order-actions{display:flex;gap:8px;flex-wrap:wrap}.legacy-order-actions form{display:flex;gap:7px;flex-wrap:wrap}.legacy-order-actions select{min-width:150px}.legacy-item-list{display:grid;gap:8px}.legacy-item{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}@media(max-width:1050px){.legacy-order-row{grid-template-columns:100px 1fr 120px 110px}.legacy-order-row .hide-tablet{display:none}.legacy-order-detail-grid{grid-template-columns:1fr}}@media(max-width:650px){.legacy-orders-head{align-items:flex-start;flex-direction:column}.legacy-order-row{grid-template-columns:72px 1fr auto;gap:9px;padding:12px}.legacy-order-row .legacy-order-payment,.legacy-order-row .legacy-order-channel,.legacy-order-row .hide-mobile{display:none}.legacy-order-price{font-size:13px}.legacy-order-customer strong{font-size:12px}}
</style>
<section class="legacy-orders-head"><div><h2>Acompanhe e gerencie os pedidos</h2><p><?= count($orders) ?> pedidos nesta visão<?= $unitId?' · unidade selecionada':'' ?>.</p></div><div class="actions"><?php if(Auth::can('orders.create')):?><a class="button primary" href="<?= Security::e(em_url('/?route=pos')) ?>">+ Nova venda</a><?php endif;?></div></section>
<nav class="legacy-order-tabs"><?php foreach($tabs as$key=>$info):?><a class="<?= $tab===$key?'active':'' ?>" href="<?= Security::e(em_url('/?route=orders&tab='.$key)) ?>"><?= Security::e($info[0]) ?></a><?php endforeach;?></nav>
<?php if($viewOrder):?><section class="card legacy-order-detail"><div class="section-head"><div><h2>Pedido #<?= (int)$viewOrder['id'] ?></h2><p class="muted"><?= Security::e(legacy_order_channel((string)$viewOrder['channel'])) ?> · <?= Security::e($viewOrder['customer_name']??'Consumidor') ?></p></div><a class="button secondary" href="<?= Security::e(em_url('/?route=orders&tab='.$tab)) ?>">Fechar</a></div><div class="legacy-order-detail-grid"><div><div class="legacy-item-list"><?php foreach($items as$item):?><div class="legacy-item"><div><strong><?= Security::e($item['name_snapshot']) ?></strong><small class="muted"><?= Security::e($item['option_names']??'') ?></small></div><div><?= Security::e((string)$item['quantity']) ?> × <?= em_money($item['unit_price_cents']) ?><br><strong><?= em_money($item['total_cents']) ?></strong></div></div><?php endforeach;?></div><p><strong>Total: <?= em_money($viewOrder['total_cents']) ?></strong></p></div><div><p><strong>Status:</strong> <span class="legacy-status <?= Security::e(legacy_order_status_class((string)$viewOrder['status'])) ?>"><?= Security::e(legacy_order_status((string)$viewOrder['status'])) ?></span></p><p><strong>Pagamento:</strong> <?= Security::e($viewOrder['payment_status']==='paid'?'Pago':em_status_label((string)$viewOrder['payment_status'])) ?></p><?php if($viewOrder['channel']==='delivery'):?><p><strong>Endereço:</strong><br><?= Security::e($viewOrder['delivery_address']??'') ?></p><p><strong>Entregador:</strong> <?= Security::e($viewOrder['delivery_name']??'Não atribuído') ?></p><?php elseif($viewOrder['channel']==='table'):?><p><strong>Mesa:</strong> <?= Security::e($viewOrder['table_name']??'—') ?></p><?php endif;?><div class="legacy-order-actions"><?php if(Auth::can('orders.manage')&&!in_array($viewOrder['status'],['completed','cancelled'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$viewOrder['id'] ?>"><input type="hidden" name="tab" value="<?= Security::e($tab) ?>"><select name="status"><?php foreach(['confirmed'=>'Confirmar','preparing'=>'Em preparo','ready'=>'Pronto','out_for_delivery'=>'Saiu para entrega','completed'=>'Concluir','cancelled'=>'Cancelar']as$st=>$label):?><option value="<?= $st ?>"><?= Security::e($label) ?></option><?php endforeach;?></select><button class="secondary">Atualizar</button></form><?php endif;?><?php if(Auth::can('delivery.assign')&&$viewOrder['channel']==='delivery'&&!in_array($viewOrder['status'],['completed','cancelled'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="assign-delivery"><input type="hidden" name="id" value="<?= (int)$viewOrder['id'] ?>"><input type="hidden" name="tab" value="<?= Security::e($tab) ?>"><select name="delivery_user_id"><option value="0">Sem entregador</option><?php foreach($deliveries as$du):?><option value="<?= (int)$du['id'] ?>"<?= em_selected($viewOrder['assigned_delivery_user_id']??0,$du['id']) ?>><?= Security::e($du['name']) ?></option><?php endforeach;?></select><button class="secondary">Atribuir</button></form><?php endif;?><?php if(Auth::can('payments.manage')&&in_array($viewOrder['payment_status'],['unpaid','failed'],true)&&!in_array($viewOrder['status'],['completed','cancelled'],true)):?><form method="post" onsubmit="return confirm('Confirmar recebimento deste pedido?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="manual-pay"><input type="hidden" name="id" value="<?= (int)$viewOrder['id'] ?>"><input type="hidden" name="tab" value="<?= Security::e($tab) ?>"><select name="manual_method"><option value="cash">Dinheiro</option><option value="card">Cartão / maquininha</option><option value="pix">Pix externo</option><option value="other">Outro</option></select><button class="primary">Receber</button></form><?php endif;?></div></div></div></section><?php endif;?>
<section class="legacy-order-list"><?php foreach($orders as$order):try{$when=(new DateTimeImmutable((string)$order['created_at'],$utc))->setTimezone($tz)->format('d/m/Y H:i');}catch(Throwable){$when=(string)$order['created_at'];}?><a class="legacy-order-row" href="<?= Security::e(em_url('/?route=orders&tab='.$tab.'&view='.(int)$order['id'])) ?>"><div class="legacy-order-id"><strong>#<?= (int)$order['id'] ?></strong><small><?= Security::e($when) ?></small></div><div class="legacy-order-customer"><strong><?= Security::e($order['customer_name']??'Consumidor') ?></strong><small><?= Security::e($order['customer_phone']??'') ?></small></div><div class="legacy-order-channel hide-tablet"><?= Security::e(legacy_order_channel((string)$order['channel'])) ?></div><div><span class="legacy-status <?= Security::e(legacy_order_status_class((string)$order['status'])) ?>"><?= Security::e(legacy_order_status((string)$order['status'])) ?></span></div><div class="legacy-order-payment hide-mobile"><?= Security::e($order['payment_status']==='paid'?'Pago':'A receber') ?></div><div class="legacy-order-price"><?= em_money($order['total_cents']) ?></div></a><?php endforeach;?><?php if(!$orders):?><div class="card"><p class="muted">Nenhum pedido nesta categoria.</p></div><?php endif;?></section>
<?php em_footer();
